  const [financeResetMode,setFinanceResetMode]=useState(false);const [financeResetPin,setFinanceResetPin]=useState("");const [financeResetConfirm,setFinanceResetConfirm]=useState("");const [financeFilterDate,setFinanceFilterDate]=useState("");
  const [financeReceipt,setFinanceReceipt]=useState<FinancialEntry|null>(null);
  const [reportDate,setReportDate]=useState(()=>dateInputValue(new Date()));const [reportPeriod,setReportPeriod]=useState<"يومي"|"شهري"|"سنوي">("يومي");const [dailyReportData,setDailyReportData]=useState<DailyReport|null>(null);const [reportMessage,setReportMessage]=useState("");
  const [appSettings,setAppSettings]=useState<AppSettings>({shopName:"",ownerName:"",financePinSet:false,appPinSet:false,theme:"dark",initialized:false});const [settingsShopName,setSettingsShopName]=useState("");const [settingsOwnerName,setSettingsOwnerName]=useState("");const [settingsFinancePin,setSettingsFinancePin]=useState("");const [settingsAppPin,setSettingsAppPin]=useState("");const [appPinAttempt,setAppPinAttempt]=useState("");const [appPinError,setAppPinError]=useState("");const [appAccessChecked,setAppAccessChecked]=useState(false);const [appUnlocked,setAppUnlocked]=useState(false);const [accessMessage,setAccessMessage]=useState("");
  const total=numericValue(totalPrice),paid=numericValue(paidAmount),discountValue=numericValue(discount),remaining=Math.max(0,total-paid-discountValue);const categories=useMemo(()=>Array.from(new Set([...defaultCategories,...designOptions.map(option=>option.category)])),[designOptions]);

  async function load(){try{setError("");const [dashboard,current,board]=await Promise.all([invoke<Dashboard>("dashboard_summary"),invoke<CurrentSession>("current_session"),invoke<WorkBoardItem[]>("work_board")]);setData(dashboard);setSession(current);setWorkItems(board)}catch{setError("تعذر قراءة بيانات المحل المحلية.")}}
  async function loadDesignOptions(){try{setDesignOptions(await invoke<DesignOption[]>("list_design_options"))}catch{setSettingsError("تعذر قراءة مكتبة الأشكال.")}}
  async function loadStorageInfo(){try{setStorage(await invoke<StorageInfo>("storage_info"))}catch{setStorageMessage("تعذر قراءة مكان حفظ البيانات.")}}
  async function loadSuppliers(){try{setSuppliers(await invoke<Supplier[]>("list_suppliers"))}catch{setSupplierMessage("تعذر قراءة الموردين.")}}
  async function loadSupplierPayments(){try{setSupplierPayments(await invoke<SupplierPayment[]>("list_supplier_payments",{supplierId:null}))}catch{setSupplierMessage("تعذر قراءة دفعات الموردين.")}}
