  async function loadAppSettings(){try{const next=await invoke<AppSettings>("get_app_settings");setAppSettings(next);setSettingsShopName(next.shopName);setSettingsOwnerName(next.ownerName);setAppUnlocked(current=>current||!next.appPinSet)}catch{setAccessMessage("تعذر قراءة الصلاحيات.")}finally{setAppAccessChecked(true)}}
  async function showHistory(){setHistoryOpen(true);try{setHistory(await invoke<SessionEntry[]>("session_history"))}catch{setError("تعذر قراءة سجل التشغيل.")}}
  async function advanceWorkItem(orderId:number){try{setMovingOrder(orderId);setError("");await invoke("advance_order_status",{orderId});await load()}catch{setError("تعذر نقل الثوب إلى المرحلة التالية.")}finally{setMovingOrder(null)}}
  async function retreatWorkItem(orderId:number){try{setMovingOrder(orderId);setError("");await invoke("retreat_order_status",{orderId});await load()}catch{setError("تعذر إرجاع الثوب إلى المرحلة السابقة.")}finally{setMovingOrder(null)}}
  function toggleOrder(orderId:number){setSelectedOrders(current=>{const next=new Set(current);next.has(orderId)?next.delete(orderId):next.add(orderId);return next})}
  async function moveSelectedOrders(){if(!selectedOrders.size){setError("حدد ثوبًا واحدًا على الأقل.");return}try{await invoke("move_orders_to_status",{orderIds:Array.from(selectedOrders),status:bulkTarget});setSelectedOrders(new Set());setError("");await load()}catch(error){setError(String(error))}}
  useEffect(()=>{void load();void loadDesignOptions();void loadStorageInfo();void loadSuppliers();void loadSupplierPayments();void loadFabrics();void loadExtraTransactions();void loadAppSettings();const interval=window.setInterval(()=>setNow(Date.now()),1000);return()=>window.clearInterval(interval)},[]);
  useEffect(()=>{if(view!=="customers")return;const timer=window.setTimeout(()=>void searchCustomerRecords(customerQuery),180);return()=>window.clearTimeout(timer)},[customerQuery,view]);
  useEffect(()=>{if(view==="add-customer"){setCustomerName("");setCustomerPhone("");setCustomerError("")}},[view]);
