  function moveBetweenNumberFields(event:KeyboardEvent<HTMLElement>){
    const target=event.target;
    if(!(target instanceof HTMLInputElement)||!target.classList.contains("numeric"))return;
    if(target.dataset.countStepper==="true"&&(event.key==="ArrowUp"||event.key==="ArrowDown"))return;
    const direction=event.key==="Enter"||event.key==="ArrowDown"?1:event.key==="ArrowUp"?-1:0;
    if(!direction)return;
    const fields=Array.from(event.currentTarget.querySelectorAll<HTMLInputElement>("input.numeric:not(:disabled)"));
    const current=fields.indexOf(target),next=fields[current+direction];
    if(current<0||!next)return;
    event.preventDefault();next.focus();if(next.type!=="date")next.select();
  }
